{
  "name": "TCP原始通信组件",
  "name_en": "TCP Raw Communication Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用作通过 TCP 与实验室仪器建立网络连接的通用基类。它负责初始化和关闭套接字连接、检查连接是否打开，以及发送和接收原始字节数据，适合为基于网络协议的仪器驱动提供底层通信能力。",
  "description_en": "This is a non-physical software communication component that serves as a generic base class for connecting to laboratory instruments over TCP. It handles socket initialization and shutdown, checks whether the connection is open, and sends and receives raw byte data, providing low-level transport functionality for network-based instrument drivers.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化 TCP 套接字连接，以便与网络仪器通信。",
      "description_en": "Initialize the TCP socket connection for communication with a networked instrument."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭并清理 TCP 连接。",
      "description_en": "Close and clean up the TCP connection."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查 TCP 连接是否处于打开状态。",
      "description_en": "Check whether the TCP connection is currently open."
    },
    {
      "action_name": "auto-raw_send",
      "description": "通过 TCP 向仪器发送原始字节数据。",
      "description_en": "Send raw byte data to the instrument over TCP."
    },
    {
      "action_name": "auto-raw_recv",
      "description": "通过 TCP 从仪器接收指定长度的原始字节数据。",
      "description_en": "Receive raw byte data of a specified length from the instrument over TCP."
    }
  ],
  "tag_hints": [
    "TCP socket communication",
    "network instrument interface",
    "raw byte send/receive",
    "instrument connection lifecycle",
    "non-physical helper component",
    "binary protocol transport"
  ]
}

